Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <cstring>
#include <vector>
#include <queue>
#include <climits>
#include <algorithm>
#include <cctype>
using namespace std;

const int MAX_N = 15;
const int INF = 1000000000;
int gridDist[MAX_N][MAX_N][MAX_N][MAX_N];
int flowCap[400][400];
char labGrid[20][20];
char reactGrid[20][20];
int dirs[4][2] = {{1,0},{0,1},{-1,0},{0,-1}};
int iterMark = 3;
int visitMark[400];

int nGrid, timeLimit;

int dfs augment(int node, int dest, int bottleneck) {
    if (node == dest) return bottleneck;
    if (visitMark[node] == iterMark) return 0;
    visitMark[node] = iterMark;
    for (int next = 0; next <= dest; ++next) {
        if (flowCap[node][next] > 0) {
            int pushed = augment(next, dest, min(bottleneck, flowCap[node][next]));
            if (pushed > 0) {
                flowCap[node][next] -= pushed;
                flowCap[next][node] += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

inline int nodeID(int x, int y) {
    return (x-1)*nGrid + (y-1);
}

int canSpreadArr[13][13];
int tempSpread[13][13];

void spread(int mark) {
    memcpy(tempSpread, canSpreadArr, sizeof(canSpreadArr));
    for (int x = 1; x <= nGrid; ++x) {
        for (int y = 1; y <= nGrid; ++y) {
            if (tempSpread[x][y] == mark) {
                for (int d = 0; d < 4; ++d) {
                    int nx = x + dirs[d][0];
                    int ny = y + dirs[d][1];
                    if (nx >= 1 && ny >= 1 && nx <= nGrid && ny <= nGrid && canSpreadArr[nx][ny] < mark && labGrid[nx][ny] != 'Y') {
                        canSpreadArr[nx][ny] = mark;
                    }
                }
            }
        }
    }
}

bool isReachable(int sx, int sy, int tx, int ty, int infx, int infy) {
    memset(canSpreadArr, 0, sizeof(canSpreadArr));
    canSpreadArr[sx][sy] = 1;
    canSpreadArr[infx][infy] = 2;
    for (int step = 0; step < 100; ++step) {
        spread(1);
        if (canSpreadArr[tx][ty] == 1) return true;
        spread(2);
        if (canSpreadArr[tx][ty] == 2) return false;
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int infx = -1, infy = -1;
    memset(gridDist, 1, sizeof(gridDist));
    cin >> nGrid >> timeLimit;

    for (int i = 1; i <= nGrid; ++i) {
        cin >> (labGrid[i] + 1);
        for (int j = 1; j <= nGrid; ++j) {
            gridDist[i][j][i][j] = 0;
            if (labGrid[i][j] == 'Z') {
                infx = i; infy = j;
            }
        }
    }

    for (int i = 1; i <= nGrid; ++i) {
        cin >> (reactGrid[i] + 1);
    }

    for (int i = 1; i <= nGrid; ++i) {
        for (int j = 1; j <= nGrid; ++j) {
            for (int d = 0; d < 4; ++d) {
                int ni = i + dirs[d][0];
                int nj = j + dirs[d][1];
                if (ni >= 1 && nj >= 1 && ni <= nGrid && nj <= nGrid) {
                    if (labGrid[i][j] != 'Y' && labGrid[ni][nj] != 'Y') {
                        gridDist[i][j][ni][nj] = 1;
                    }
                }
            }
        }
    }

    for (int k = 1; k <= nGrid; ++k) {
        for (int l = 1; l <= nGrid; ++l) {
            for (int i = 1; i <= nGrid; ++i) {
                for (int j = 1; j <= nGrid; ++j) {
                    for (int u = 1; u <= nGrid; ++u) {
                        for (int v = 1; v <= nGrid; ++v) {
                            gridDist[i][j][u][v] = min(gridDist[i][j][u][v], gridDist[i][j][k][l] + gridDist[k][l][u][v]);
                        }
                    }
                }
            }
        }
    }

    int src = nGrid * nGrid * 2 + 1;
    int dst = nGrid * nGrid * 2 + 2;

    for (int i = 1; i <= nGrid; ++i) {
        for (int j = 1; j <= nGrid; ++j) {
            if (isdigit(labGrid[i][j])) {
                flowCap[src][nodeID(i,j)] = labGrid[i][j] - '0';
            }
            if (isdigit(reactGrid[i][j])) {
                flowCap[nGrid*nGrid + nodeID(i,j)][dst] = reactGrid[i][j] - '0';
            }

            if (isdigit(labGrid[i][j])) {
                for (int u = 1; u <= nGrid; ++u) {
                    for (int v = 1; v <= nGrid; ++v) {
                        if (labGrid[i][j] > '0' && reactGrid[u][v] > '0') {
                            if (isdigit(reactGrid[u][v]) && gridDist[i][j][u][v] <= timeLimit && isReachable(i,j,u,v,infx,infy)) {
                                flowCap[nodeID(i,j)][nGrid*nGrid + nodeID(u,v)] = 1000;
                            }
                        }
                    }
                }
            }
        }
    }

    int totalFlow = 0;
    int push;
    while ((push = augment(src, dst, 1000))) {
        totalFlow += push;
        ++iterMark;
    }

    cout << totalFlow << endl;
    return 0;
}
